\label{pa-ch-curves}

Let \(k\) be a field and \(C\to\Spec k\) a smooth, proper, geometrically
integral curve.

\begin{definition}[Divisor line bundle]
  \label{pa-def-divisor-line-bundle}
  \dcref{II.6}
  \cite{hartshorne-ag}
  For \(D=\sum n_P[P]\), put
  \[
    \mathcal O_C(D)_P=\{f\in K(C):\operatorname{ord}_P(f)+n_P\ge0\}.
  \]
\end{definition}

\begin{lemma}[Divisor bundles and tensor products]
  \label{pa-lem-divisor-bundle-tensor}
  \dcref{II.6}
  \uses{pa-def-divisor-line-bundle}
  \cite{hartshorne-ag}
  The sheaf \(\mathcal O_C(D)\) is invertible and
  \(\mathcal O_C(D+E)\cong\mathcal O_C(D)\otimes\mathcal O_C(E)\).
\end{lemma}

\begin{proof}
  A uniformizer at \(P\) identifies the stalk with
  \(\pi_P^{-n_P}\mathcal O_{C,P}\); multiplication in \(K(C)\) gives the
  tensor identity.
\end{proof}

\begin{lemma}[Principal divisors have degree zero]
  \label{pa-lem-principal-degree-zero}
  \dcref{II.6}
  \uses{pa-def-divisors}
  \cite{hartshorne-ag,papaioannou-rr}
  \(\deg\operatorname{div}(f)=0\) for \(f\in K(C)^\times\).
\end{lemma}

\begin{proof}
  The product formula for the finite extension \(K(C)/k(t)\) gives the
  weighted sum of valuations as zero, which is precisely the displayed degree.
\end{proof}

\begin{lemma}[Adding a closed point]
  \label{pa-lem-divisor-exact-sequence}
  \dcref{II.6}
  \uses{pa-def-divisor-line-bundle}
  \cite{hartshorne-ag}
  For a closed point \(P\),
  \[
    0\to\mathcal O_C(D-P)\to\mathcal O_C(D)\to\kappa(P)\to0
  \]
  is exact.
\end{lemma}

\begin{proof}
  The first map is an isomorphism off \(P\).  At \(P\), the quotient of the
  two free rank-one stalks is
  \(\mathcal O_{C,P}/(\pi_P)\cong\kappa(P)\).
\end{proof}

\begin{definition}[Genus]
  \label{pa-def-genus}
  \dcref{IV.1,custom}
  \cite{milne-av,kleiman-picard}
  The genus of \(C\) is
  \[
    g(C)=\dim_k H^1(C,\mathcal O_C).
  \]
\end{definition}

Proper coherent-cohomology finiteness makes the displayed dimension finite;
geometric integrality identifies it with the usual genus after any field
extension.

\begin{definition}[Divisors and degree]
  \label{pa-def-divisors}
  \dcref{II.6}
  \cite{hartshorne-ag,papaioannou-rr}
  A divisor is \(D=\sum_xn_x[x]\) with finite support on the closed points of
  \(C\), and
  \[
    \deg D=\sum_xn_x[\kappa(x):k].
  \]
  Principal divisors are \(\operatorname{div}(f)\) for
  \(f\in K(C)^\times\); divisor classes form \(\operatorname{Pic}(C)\).
\end{definition}

\begin{theorem}[Riemann--Roch]
  \label{pa-thm-riemann-roch}
  \dcref{IV.1}
  \uses{pa-def-genus,pa-def-divisors}
  \cite{hartshorne-ag,papaioannou-rr}
  There is a canonical divisor \(K_C\) of degree \(2g(C)-2\) and
  \[
    \dim_kH^0(C,\mathcal O_C(D))-
    \dim_kH^0(C,\mathcal O_C(K_C-D))
    =\deg D+1-g(C).
  \]
\end{theorem}

\begin{proof}
  Serre duality gives
  \(H^1(C,\mathcal O_C(D))^\vee\simeq
  H^0(C,\mathcal O_C(K_C-D))\).  For a closed point \(P\), the exact sequence
  \[
    0\longrightarrow\mathcal O_C(D-P)\longrightarrow\mathcal O_C(D)
    \longrightarrow\kappa(P)\longrightarrow0
  \]
  changes the Euler characteristic by \([\kappa(P):k]\).  Serre vanishing
  starts the induction at large degree, giving
  \(\chi(\mathcal O_C(D))=\deg D+\chi(\mathcal O_C)\).  Since
  \(\chi(\mathcal O_C)=1-g(C)\), duality yields the formula.
\end{proof}

\label{pa-ch-cohomology}

\begin{definition}[Module-valued cohomology]
  \label{pa-def-module-cohomology}
  \dcref{III.1,custom}
  \cite{stacks-project}
  For a sheaf \(\mathcal F\) of \(k\)-modules on \(C\), put
  \(H^i(C,\mathcal F)=\operatorname{Ext}^i(k_C,\mathcal F)\), with \(k_C\)
  the constant sheaf.
\end{definition}

\begin{proposition}[The Cech short exact sequence]
  \label{pa-prop-cech-short-exact}
  \dcref{III.1}
  \uses{pa-def-cech-complex,pa-lem-affine-vanishing}
  \cite{stacks-project}
  For \(C=U\cup V\) as above,
  \[
    0\to\Gamma(C,\mathcal F)\to\mathcal F(U)\oplus\mathcal F(V)
    \to\mathcal F(U\cap V)\to H^1(C,\mathcal F)\to0
  \]
  is exact.
\end{proposition}

\begin{proof}
  The sheaf equalizer gives exactness at the first three terms, while affine
  acyclicity identifies the cokernel with \(H^1\).
\end{proof}

\begin{definition}[Two-affine Cech complex]
  \label{pa-def-cech-complex}
  \dcref{III.1}
  \cite{stacks-project}
  For \(C=U\cup V\) with \(U,V,U\cap V\) affine, define
  \[
    \check C^0(\mathcal F)=\mathcal F(U)\oplus\mathcal F(V),\qquad
    \check C^1(\mathcal F)=\mathcal F(U\cap V),
  \]
  with \(d(s,t)=s|_{U\cap V}-t|_{U\cap V}\).
\end{definition}

\begin{lemma}[Cech computes \(H^0\) and \(H^1\)]
  \label{pa-lem-cech-computes}
  \dcref{III.1}
  \uses{pa-def-cech-complex}
  \cite{stacks-project}
  For quasi-coherent \(\mathcal F\),
  \(H^0(C,\mathcal F)=\ker d\) and \(H^1(C,\mathcal F)=\operatorname{coker}d\).
\end{lemma}

\begin{proof}
  Quasi-coherent sheaves are acyclic on affine opens and their intersections,
  so the Cech-to-derived spectral sequence for this cover degenerates.
\end{proof}

\begin{lemma}[Affine cohomology vanishes]
  \label{pa-lem-affine-vanishing}
  \dcref{III.1}
  \cite{stacks-project}
  If \(W\) is affine and \(\mathcal F\) is quasi-coherent, then
  \(H^i(W,\mathcal F)=0\) for \(i>0\).
\end{lemma}

\begin{proof}
  For \(W=\Spec A\), write \(\mathcal F=\widetilde M\).  The section functor
  is the exact identity on \(A\)-modules, so its positive derived functors
  vanish.
\end{proof}

\begin{lemma}[Relative curves have cohomological dimension one]
  \label{pa-lem-h2-vanishing}
  \dcref{III.1}
  \uses{pa-lem-cech-computes}
  \cite{stacks-project}
  For every \(T\) and quasi-coherent \(\mathcal F\) on \(C_T\),
  \(H^i(C_T,\mathcal F)=0\) for \(i\ge2\).
\end{lemma}

\begin{proof}
  Base change preserves a finite affine cover with affine finite intersections.
  Its Cech complex has no terms in degrees above one.
\end{proof}

\begin{proposition}[Cech base change]
  \label{pa-prop-cech-base-change}
  \dcref{III.12}
  \uses{pa-def-cech-complex}
  \cite{stacks-project}
  For \(k\subset k'\), the Cech complex of \(\mathcal F_{k'}\) is
  \(\check C^\bullet(\mathcal F)\otimes_k k'\).
\end{proposition}

\begin{proof}
  On affine opens, sections are modules; localization and tensor products
  commute with the flat field extension.  The restriction maps are therefore
  the scalar extensions of \(d\).
\end{proof}

\begin{lemma}[Flat base change on cohomology]
  \label{pa-lem-flat-cohomology}
  \dcref{III.12}
  \uses{pa-prop-cech-base-change,pa-lem-cech-computes}
  \cite{stacks-project}
  The natural map
  \(H^i(C,\mathcal F)\otimes_k k'\to H^i(C_{k'},\mathcal F_{k'})\)
  is an isomorphism.
\end{lemma}

\begin{proof}
  Tensoring with a field is exact, hence commutes with the kernel and cokernel
  of the two-term Cech differential in \ref{pa-lem-cech-computes}.
\end{proof}

\begin{theorem}[Finiteness and base change]
  \label{pa-thm-cohomology}
  \dcref{III.12}
  \uses{pa-def-genus}
  \cite{stacks-project}
  If \(\mathcal F\) is coherent on \(C\), then \(H^i(C,\mathcal F)\) is finite
  dimensional over \(k\), and for every extension \(k\subset k'\),
  \[
    H^i(C,\mathcal F)\otimes_k k'\cong
    H^i(C_{k'},\mathcal F_{k'}).
  \]
\end{theorem}

\begin{proof}
  A finite affine cover of the proper curve gives a bounded Cech complex of
  finite-dimensional \(k\)-vector spaces computing coherent cohomology.
  Extending scalars tensors this complex with \(k'\); flatness of a field
  extension commutes with its cohomology.  This proves both finiteness and the
  displayed base-change isomorphism.
\end{proof}

\begin{proposition}[Global functions]
  \label{pa-prop-global-functions}
  \dcref{III.1}
  \cite{hartshorne-ag,stacks-project}
  Geometric integrality and properness imply \(H^0(C,\mathcal O_C)=k\).
\end{proposition}

\begin{proof}
  Apply base change to \(H^0\) and an algebraic closure \(\bar k\).  The
  proper integral scheme \(C_{\bar k}\) has only constant global functions,
  so
  \(H^0(C,\mathcal O_C)\otimes_k\bar k\simeq\bar k\).  The structural
  inclusion of \(k\) is consequently an isomorphism.
\end{proof}

\begin{proposition}[Picard tangent space]
  \label{pa-prop-picard-tangent}
  \dcref{5.11}
  \uses{pa-def-genus,pa-thm-cohomology}
  \cite[Thm.~5.11]{kleiman-picard}
  For the identity element of the relative Picard scheme,
  \[
    T_0\operatorname{Pic}_{C/k}\cong H^1(C,\mathcal O_C),
    \qquad \dim_kT_0\operatorname{Pic}_{C/k}=g(C).
  \]
\end{proposition}

\begin{proof}
  Put \(k[\epsilon]=k[\epsilon]/(\epsilon^2)\).  The kernel of the reduction
  map on the etale Picard functor is computed by
  \[
    1\longrightarrow1+\epsilon\mathcal O_C
    \longrightarrow\mathcal O_{C_{k[\epsilon]}}^\times
    \longrightarrow\mathcal O_C^\times\longrightarrow1.
  \]
  The first term is additively \(\mathcal O_C\), so the kernel is
  \(H^1(C,\mathcal O_C)\).  Scalar substitutions
  \(\epsilon\mapsto a\epsilon\) supply the vector-space structure and the
  preceding base-change theorem gives its compatibility with \(k'\).
\end{proof}

\label{pa-ch-picard}

\begin{definition}[Rigidified line bundles]
  \label{pa-def-rigidified-line-bundle}
  \dcref{2.2}
  \cite{kleiman-picard}
  If \(C_T\to T\) has a section \(s\), a rigidification of \(\mathcal L\) is
  an isomorphism \(s^*\mathcal L\cong\mathcal O_T\).
\end{definition}

\begin{lemma}[Rigidification identifies the quotient]
  \label{pa-lem-rigidification}
  \dcref{2.2}
  \uses{pa-def-rigidified-line-bundle,pa-def-picard}
  \cite{kleiman-picard}
  Relative line-bundle classes modulo \(\operatorname{Pic}(T)\) are
  represented by rigidified bundles, uniquely up to a unique rigidified
  isomorphism.
\end{lemma}

\begin{proof}
  Tensoring by \(p^*s^*\mathcal L^{-1}\), where \(p:C_T\to T\), produces a
  rigidification.  An isomorphism between two such representatives restricts
  to the identity on \(s(T)\), and the quotient ambiguity has been removed.
\end{proof}

\begin{lemma}[The relative Picard presheaf is a group presheaf]
  \label{pa-lem-picard-presheaf-group}
  \dcref{2.2}
  \uses{pa-def-picard}
  \cite{kleiman-picard}
  Pullback makes \(T\mapsto\operatorname{Pic}^{\sharp}_{C/k}(T)\) a
  contravariant commutative group-valued functor.
\end{lemma}

\begin{proof}
  Pullback preserves tensor product, duals, and the trivial bundle, and it
  carries bundles pulled back from \(T\) to bundles pulled back from \(T'\).
  These operations therefore descend to the quotient.
\end{proof}

\begin{lemma}[Etale sheafification preserves the group law]
  \label{pa-lem-etale-sheaf-group}
  \dcref{2.2}
  \uses{pa-lem-picard-presheaf-group}
  \cite{kleiman-picard}
  The etale sheaf associated to
  \(\operatorname{Pic}^{\sharp}_{C/k}\) is a commutative group sheaf.
\end{lemma}

\begin{proof}
  Sheafification is left exact and preserves finite products.  The operations
  and their identities and inverses sheafify from the presheaf identities.
\end{proof}

\begin{proposition}[Invertible Quot locus]
  \label{pa-prop-invertible-quot-locus}
  \dcref{4.8}
  \cite{kleiman-picard,nitsure-hilbert-quot}
  For a fixed Hilbert polynomial, the Quot scheme contains an open locus
  parameterising quotients whose target is an invertible sheaf on \(C_T\).
\end{proposition}

\begin{proof}
  Flatness of the quotient is an open condition, and on a relative smooth
  curve a flat coherent quotient with rank one and fixed Hilbert polynomial is
  locally free of rank one.  The invertibility locus is therefore open.
\end{proof}

\begin{lemma}[Generator changes give the Picard equivalence]
  \label{pa-lem-generator-equivalence}
  \dcref{4.8}
  \uses{pa-prop-invertible-quot-locus}
  \cite{kleiman-picard}
  On the invertible Quot locus, two evaluation quotients define the same
  Picard class exactly when they differ fppf-locally by a change of basis of
  the generating module.
\end{lemma}

\begin{proof}
  An isomorphism of target line bundles carries one chosen generating basis to
  the other.  Conversely, a basis change gives an isomorphic quotient.  The
  matrices are defined after the fppf cover on which the generating module is
  free.
\end{proof}

\begin{lemma}[Universal class after etale descent]
  \label{pa-lem-universal-class-descent}
  \dcref{4.3}
  \uses{pa-lem-rigidification,pa-lem-generator-equivalence}
  \cite{kleiman-picard}
  Local universal line bundles on the Quot charts differ on overlaps by
  pullbacks from the base, and hence define a universal class in the etale
  Picard sheaf.
\end{lemma}

\begin{proof}
  The ratio of two line bundles representing the same relative class is
  pulled back from the base by the quotient relation.  These ratios satisfy
  the cocycle condition, so etale descent glues the classes; changing a
  representative tensors it by a base line bundle.
\end{proof}

\begin{lemma}[Flattening stratification for Quot]
  \label{pa-lem-flattening-stratification}
  \dcref{1.1}
  \cite{nitsure-hilbert-quot}
  A coherent Quot family has a universal locally closed stratification of the
  base on which it is flat with fixed Hilbert polynomial.
\end{lemma}

\begin{proof}
  After a projective embedding, Fitting ideals of finitely many graded pieces
  cut out the prescribed ranks.  Their universal property gives the required
  stratification.
\end{proof}

\begin{lemma}[The invertible locus is open]
  \label{pa-lem-invertible-open}
  \dcref{4.8}
  \uses{pa-lem-flattening-stratification,pa-prop-invertible-quot-locus}
  \cite{kleiman-picard}
  The locus of invertible rank-one quotients in a flat Quot family is open.
\end{lemma}

\begin{proof}
  The locally free locus of a flat coherent sheaf is open; fixed rank one
  identifies it with the invertible quotient locus.
\end{proof}

\begin{definition}[Relative Picard functor]
  \label{pa-def-picard}
  \dcref{2.2}
  \cite[Def.~2.2]{kleiman-picard}
  For \(T\in(\Sch/k)\), put \(C_T=C\times_kT\) and
  \[
    \operatorname{Pic}^{\sharp}_{C/k}(T)=
    \operatorname{Pic}(C_T)/\operatorname{Pic}(T).
  \]
  Let \(\operatorname{Pic}_{(C/k)\et}\) be its associated etale sheaf.
\end{definition}

\begin{proposition}[Group law]
  \label{pa-prop-picard-group}
  \dcref{2.2}
  \uses{pa-def-picard}
  \cite{kleiman-picard}
  Tensor product, the trivial bundle, and duality make
  \(\operatorname{Pic}_{(C/k)\et}\) a commutative group-valued functor.
\end{proposition}

\begin{proof}
  Tensor product, the trivial bundle, and dualisation define the group
  operations on \(\operatorname{Pic}(C_T)\).  They are compatible with
  pullback from \(T\), and hence descend to the quotient and its etale
  sheaf.  The canonical symmetry and associativity constraints make the
  resulting group commutative.
\end{proof}

\begin{theorem}[Etale Picard representability]
  \label{pa-thm-picard-representability}
  \dcref{4.8}
  \uses{pa-def-picard}
  \cite[Thm.~4.8]{kleiman-picard}
  The sheaf \(\operatorname{Pic}_{(C/k)\et}\) is represented by a separated
  \(k\)-scheme \(\operatorname{Pic}_{C/k}\), locally of finite type, with open
  quasi-projective degree pieces
  \[
    \operatorname{Pic}_{C/k}=\coprod_{d\in\mathbb Z}\operatorname{Pic}^d_{C/k}.
  \]
\end{theorem}

\begin{proof}
  Choose a relatively ample line bundle on \(C\).  For \(n\) sufficiently
  large, every line bundle in a fixed degree range is \(n\)-regular and is
  represented by a quotient of a fixed finite-dimensional space of sections.
  Grothendieck's Quot scheme supplies the parameter space.  The change of
  generators gives an etale-locally trivial equivalence relation, and
  faithfully flat descent identifies its quotient with the corresponding
  open of the Picard sheaf.  Gluing degree ranges yields the separated,
  locally finite-type scheme and its open quasi-projective components.
\end{proof}

\begin{proposition}[Universal line bundle]
  \label{pa-prop-poincare}
  \dcref{4.3}
  \uses{pa-thm-picard-representability}
  \cite[Ex.~4.3]{kleiman-picard}
  After etale localisation on \(\operatorname{Pic}_{C/k}\), the universal class
  is represented by a line bundle on
  \(C\times_k\operatorname{Pic}_{C/k}\), unique up to tensoring by a pullback
  from \(\operatorname{Pic}_{C/k}\).
\end{proposition}

\begin{proof}
  The universal quotient on the Quot scheme gives a universal line bundle
  after restricting to the invertible locus.  On overlaps two choices differ
  by tensoring with the pullback of a line bundle from the parameter space.
  The etale topology kills this descent obstruction, producing a universal
  class on \(C\times_k\operatorname{Pic}_{C/k}\), unique up to such a
  pullback.
\end{proof}

\label{pa-ch-divisors}

\begin{definition}[Relative effective divisor]
  \label{pa-def-relative-effective-divisor}
  \dcref{3.7}
  \cite{kleiman-picard}
  For \(T\in(\Sch/k)\), a relative effective divisor on \(C_T\) is a closed
  subscheme finite and flat over \(T\).
\end{definition}

\begin{lemma}[Relative effective divisors are Cartier]
  \label{pa-lem-relative-divisor-cartier}
  \dcref{3.7}
  \uses{pa-def-relative-effective-divisor}
  \cite{kleiman-picard}
  Every relative effective divisor on the smooth relative curve \(C_T/T\) is
  an effective Cartier divisor.
\end{lemma}

\begin{proof}
  The ideal is finite flat over \(T\) and has fibrewise height one.  Smooth
  relative dimension one makes the local rings regular of dimension one, so
  each ideal is locally generated by a non-zero divisor.
\end{proof}

\begin{lemma}[The Hilbert functor of divisors]
  \label{pa-lem-divisor-hilbert-functor}
  \dcref{3.7}
  \uses{pa-def-relative-effective-divisor,pa-lem-relative-divisor-cartier}
  \cite{kleiman-picard,nitsure-hilbert-quot}
  The degree-\(n\) relative-divisor functor is the length-\(n\) open-and-closed
  subfunctor of \(\operatorname{Hilb}_{C/k}\).
\end{lemma}

\begin{proof}
  A finite flat divisor has constant fibre length \(n\), hence a fixed Hilbert
  polynomial.  Conversely, a flat length-\(n\) family on a smooth curve is
  Cartier by \ref{pa-lem-relative-divisor-cartier}.
\end{proof}

\begin{lemma}[Symmetric powers represent divisors]
  \label{pa-lem-symmetric-power-represents}
  \dcref{III.6}
  \uses{pa-def-symmetric-power,pa-lem-divisor-hilbert-functor}
  \cite{milne-av,kleiman-picard}
  The length-\(n\) Hilbert scheme of \(C\) is \(C^{(n)}\); it is smooth and
  proper of relative dimension \(n\).
\end{lemma}

\begin{proof}
  Locally on \(C\), a length-\(n\) subscheme is given by a monic degree-\(n\)
  polynomial, whose coefficients give smooth coordinates.  The Hilbert scheme
  is projective, and the symmetric-group quotient has the same functor of
  effective divisors.
\end{proof}

\begin{lemma}[Degree of the divisor line bundle]
  \label{pa-lem-effective-divisor-degree}
  \dcref{3.7}
  \uses{pa-lem-relative-divisor-cartier,pa-def-divisor-line-bundle}
  \cite{kleiman-picard}
  If \(D\) has relative degree \(n\), then \(\mathcal O_{C_T}(D)\) has degree
  \(n\) on every geometric fibre.
\end{lemma}

\begin{proof}
  Restrict to a geometric fibre.  The Cartier divisor exact sequence identifies
  the length of \(\mathcal O_D\) with the degree of
  \(\mathcal O_C(D)\); flatness makes this length equal to \(n\).
\end{proof}

\begin{lemma}[Fibres of the effective divisor map]
  \label{pa-lem-effective-map-fibres}
  \dcref{3.7}
  \uses{pa-prop-effective-map,pa-lem-principal-degree-zero}
  \cite{kleiman-picard}
  A geometric fibre of \(C^{(n)}\to\operatorname{Pic}^n_{C/k}\) is the complete
  linear system of any divisor in that fibre.
\end{lemma}

\begin{proof}
  Equality of classes is equivalent to differing by a principal divisor.
  Effective divisors linearly equivalent to \(D\) are precisely zero divisors of
  nonzero sections of \(\mathcal O_C(D)\), modulo scalar multiplication.
\end{proof}

\begin{lemma}[Base change of relative divisors]
  \label{pa-lem-relative-divisor-base-change}
  \dcref{3.7}
  \uses{pa-def-relative-effective-divisor,pa-lem-relative-divisor-cartier}
  \cite{kleiman-picard}
  If \(T'\to T\), the pullback of a relative effective divisor
  \(D\subset C_T\) is a relative effective divisor on \(C_{T'}\), and
  \(\mathcal O(D)\) pulls back to \(\mathcal O(D_{T'})\).
\end{lemma}

\begin{proof}
  Finite flatness and the Cartier condition are stable under base change.
  Pullback of the invertible ideal of \(D\), followed by dualisation, gives
  the line-bundle identity.
\end{proof}

\begin{proposition}[Naturality of the effective divisor map]
  \label{pa-prop-effective-map-natural}
  \dcref{3.7}
  \uses{pa-lem-relative-divisor-base-change,pa-prop-effective-map}
  \cite{kleiman-picard}
  The maps \(C^{(n)}(T)\to\operatorname{Pic}^n_{C/k}(T)\) commute with every
  base change \(T'\to T\).
\end{proposition}

\begin{proof}
  This is the line-bundle identity of
  \ref{pa-lem-relative-divisor-base-change}, together with the definition of
  the relative Picard quotient.
\end{proof}

\begin{definition}[Symmetric powers]
  \label{pa-def-symmetric-power}
  \dcref{III.6}
  \cite{milne-av,kleiman-picard}
  For \(n\ge0\), \(C^{(n)}\) is the quotient of \(C^n\) by the symmetric group.
  Its geometric points are effective divisors of degree \(n\).
\end{definition}

The Hilbert scheme of length-\(n\) subschemes of a smooth curve represents
this functor.  Its local coordinates are the coefficients of a monic
polynomial, so it is smooth of relative dimension \(n\).

\begin{proposition}[Effective divisor map]
  \label{pa-prop-effective-map}
  \dcref{3.7}
  \uses{pa-def-symmetric-power,pa-def-picard}
  \cite[Thm.~3.7]{kleiman-picard}
  The assignment \(D\mapsto\mathcal O_C(D)\) gives a morphism
  \[
    C^{(n)}\longrightarrow\operatorname{Pic}^n_{C/k}
  \]
  whose geometric fibres are complete linear systems.
\end{proposition}

\begin{proof}
  A finite flat effective divisor is Cartier on the smooth relative curve,
  hence determines an invertible sheaf of degree \(n\).  The construction is
  compatible with pullback and factors through the etale Picard sheaf.  Two
  divisors have the same image exactly when their difference is principal,
  which identifies the geometric fibre with the complete linear system.
\end{proof}

\begin{definition}[Abel--Jacobi map]
  \label{pa-def-abel-jacobi}
  \dcref{III.6}
  \uses{pa-def-picard}
  \cite{milne-av,kleiman-picard}
  For \(P_0\in C(k)\), set
  \[
    \iota_{P_0}(Q)=[\mathcal O_C(Q-P_0)].
  \]
  The rigidified diagonal line bundle makes
  \(\iota_{P_0}:C\to\operatorname{Pic}^0_{C/k}\) a morphism with
  \(\iota_{P_0}(P_0)=0\).
\end{definition}

\begin{proof}
  The diagonal divisor on \(C\times C\), corrected by the two fibres through
  \(P_0\), is rigidified along \(P_0\).  Its restriction over \(Q\) is
  \(\mathcal O_C(Q-P_0)\).  The universal property of the relative Picard
  sheaf therefore gives the stated morphism and sends \(P_0\) to the identity.
\end{proof}

\label{pa-ch-pic0}

\begin{lemma}[Degree is locally constant]
  \label{pa-lem-degree-locally-constant}
  \dcref{5.1}
  \uses{pa-def-picard}
  \cite{kleiman-picard}
  The degree of a line bundle in a flat family over \(T\) is locally constant
  on \(T\).
\end{lemma}

\begin{proof}
  The Hilbert polynomial of a flat family is locally constant.  On a curve its
  linear coefficient is the degree, so the assertion follows.
\end{proof}

\begin{lemma}[Degree components are open and closed]
  \label{pa-lem-degree-open-closed}
  \dcref{5.1}
  \uses{pa-lem-degree-locally-constant,pa-thm-picard-representability}
  \cite{kleiman-picard}
  Each \(\operatorname{Pic}^d_{C/k}\) is an open-and-closed subscheme.
\end{lemma}

\begin{proof}
  It is the inverse image of \(d\) under the locally constant degree function
  of \ref{pa-lem-degree-locally-constant}.
\end{proof}

\begin{lemma}[Translations between degree components]
  \label{pa-lem-pic0-translation}
  \dcref{5.1}
  \uses{pa-prop-picard-group,pa-lem-degree-open-closed}
  \cite{kleiman-picard}
  Tensoring by a degree-\(r\) line bundle is an isomorphism
  \(\operatorname{Pic}^d_{C/k}\cong\operatorname{Pic}^{d+r}_{C/k}\).
\end{lemma}

\begin{proof}
  The tensor law adds degrees, and tensoring by the dual line bundle is the
  inverse morphism.
\end{proof}

\begin{lemma}[Large-degree effective representatives]
  \label{pa-lem-large-degree-effective}
  \dcref{IV.1}
  \uses{pa-thm-riemann-roch}
  \cite{hartshorne-ag,papaioannou-rr}
  If \(n\ge2g(C)-1\), every degree-\(n\) line bundle has a nonzero section and
  is \(\mathcal O_C(D)\) for an effective divisor \(D\) of degree \(n\).
\end{lemma}

\begin{proof}
  Riemann--Roch and the negative-degree vanishing give
  \(h^0(C,\mathcal L)=n+1-g(C)>0\).  The zero divisor of a nonzero section
  has the required degree and line bundle.
\end{proof}

\begin{lemma}[The Picard obstruction lies in \(H^2\)]
  \label{pa-lem-picard-obstruction}
  \dcref{5.11}
  \uses{pa-lem-h2-vanishing}
  \cite{kleiman-picard}
  The obstruction to extending a line bundle across a square-zero thickening
  is a class in \(H^2(C,\mathcal O_C)\).
\end{lemma}

\begin{proof}
  Lift local trivializations and compare their transition functions.  The
  failure of the lifted transitions to satisfy the cocycle condition is an
  additive \(2\)-cocycle in \(\mathcal O_C\), whose class is the obstruction.
\end{proof}

\begin{proposition}[Smoothness of the identity component]
  \label{pa-prop-pic0-smooth}
  \dcref{5.11}
  \uses{pa-lem-picard-obstruction,pa-lem-h2-vanishing,pa-prop-picard-group}
  \cite{kleiman-picard}
  \(\operatorname{Pic}^0_{C/k}\) is smooth.
\end{proposition}

\begin{proof}
  The obstruction vanishes by \ref{pa-lem-h2-vanishing}, so the infinitesimal
  lifting criterion gives smoothness at the identity.  Translations carry this
  point to every point of the identity component.
\end{proof}

\begin{proposition}[Properness from a symmetric power]
  \label{pa-prop-pic0-proper}
  \dcref{5.4}
  \uses{pa-lem-large-degree-effective,pa-prop-effective-map}
  \cite{kleiman-picard}
  \(\operatorname{Pic}^0_{C/k}\) is proper.
\end{proposition}

\begin{proof}
  For \(n\ge2g(C)-1\), the proper scheme \(C^{(n)}\) maps surjectively to
  \(\operatorname{Pic}^n_{C/k}\) by
  \ref{pa-lem-large-degree-effective}.  Translating by a fixed degree-\(n\)
  class identifies this component with \(\operatorname{Pic}^0_{C/k}\);
  properness descends along the proper surjective Abel map.
\end{proof}

\begin{lemma}[Identity component is a subgroup]
  \label{pa-lem-identity-component-subgroup}
  \dcref{5.1}
  \uses{pa-prop-picard-group,pa-def-pic0}
  \cite{kleiman-picard}
  The connected component of the identity in a group scheme locally of finite
  type is an open-and-closed subgroup scheme.
\end{lemma}

\begin{proof}
  Connected components are open in a locally Noetherian group scheme.
  Multiplication and inversion preserve the component containing the identity,
  while translations carry it to every other component.
\end{proof}

\begin{lemma}[Geometric connectedness of the identity component]
  \label{pa-lem-pic0-geometrically-connected}
  \dcref{5.1}
  \uses{pa-lem-identity-component-subgroup}
  \cite{kleiman-picard}
  The identity component of \(\operatorname{Pic}_{C/k}\) remains connected
  after every field extension.
\end{lemma}

\begin{proof}
  After base change to an algebraic closure, translations identify all
  components.  The component containing the rational identity is therefore
  geometrically connected, and descent gives the assertion.
\end{proof}

\begin{lemma}[Dimension is the tangent dimension]
  \label{pa-lem-pic0-dimension-tangent}
  \dcref{5.11}
  \uses{pa-prop-picard-tangent,pa-prop-pic0-smooth}
  \cite{kleiman-picard}
  For the smooth identity component,
  \(\dim\operatorname{Pic}^0_{C/k}=\dim_kH^1(C,\mathcal O_C)=g(C)\).
\end{lemma}

\begin{proof}
  A smooth finite-type scheme has dimension equal to the dimension of its
  Zariski tangent space at a rational point.  Use the tangent identification
  and the definition of \(g(C)\).
\end{proof}

\begin{definition}[Picard variety]
  \label{pa-def-pic0}
  \dcref{5.1}
  \uses{pa-thm-picard-representability,pa-prop-picard-group}
  \cite[Lem.~5.1]{kleiman-picard}
  Define
  \[
    \operatorname{Pic}^0_{C/k}:=(\operatorname{Pic}_{C/k})^0,
  \]
  the connected component containing the trivial line bundle.
\end{definition}

The degree is locally constant in a flat family, so the identity component is
contained in the degree-zero component.  The Abel map for sufficiently large
degree shows that these components differ only by translation.

\begin{theorem}[Picard variety is an abelian variety]
  \label{pa-thm-pic0-abelian}
  \dcref{5.4,5.11,5.13,5.14}
  \uses{pa-def-pic0,pa-prop-picard-tangent,pa-def-genus}
  \cite[Thm.~5.4 and Cors.~5.13--5.14]{kleiman-picard}
  The scheme \(\operatorname{Pic}^0_{C/k}\) is a smooth proper commutative
  geometrically connected group scheme, hence an abelian variety, and
  \[
    \dim\operatorname{Pic}^0_{C/k}=g(C).
  \]
\end{theorem}

\begin{proof}
  For \(n>2g(C)-2\), Riemann--Roch gives \(H^1(C,\mathcal L)=0\) for every
  line bundle of degree \(n\).  The proper symmetric power \(C^{(n)}\) maps
  surjectively to \(\operatorname{Pic}^n_{C/k}\); translating by a fixed
  degree-\(n\) class proves that \(\operatorname{Pic}^0_{C/k}\) is proper.
  Its tangent space is \(H^1(C,\mathcal O_C)\), while
  \(H^2(C,\mathcal O_C)=0\) removes the obstruction to lifting line bundles
  across square-zero thickenings.  Thus it is smooth at the identity and,
  by translation, everywhere.  The identity-component theorem gives
  geometric connectedness and the group structure, so it is an abelian
  variety of dimension \(g(C)\).
\end{proof}

\begin{proposition}[Degree-zero characterisation]
  \label{pa-prop-pic0-degree}
  \dcref{5.3}
  \uses{pa-def-pic0}
  \cite{kleiman-picard}
  A geometric point of \(\operatorname{Pic}_{C/k}\) lies in
  \(\operatorname{Pic}^0_{C/k}\) exactly when its line bundle has degree zero.
\end{proposition}

\begin{proof}
  Degree is constant on connected components, so \(\operatorname{Pic}^0\) is
  contained in the degree-zero locus.  Conversely, after an algebraic
  closure, any degree-zero class can be written as
  \([\mathcal O_C(D-nP_0)]\) for \(n\) sufficiently large by
  Riemann--Roch.  It lies in the component of the identity, and descent from
  the algebraic closure gives the assertion over \(k\).
\end{proof}

\label{pa-ch-albanese}

\begin{theorem}[Rigidity]
  \label{pa-thm-rigidity}
  \dcref{I.2}
  \cite{milne-av,mumford-av}
  If \(X\) is proper and geometrically connected, \(Y\) is reduced, \(A\) is
  an abelian variety, and \(f:X\times_kY\to A\) is constant on
  \(\{x_0\}\times Y\), then \(f\) factors uniquely through \(X\).  In
  particular a pointed morphism from an abelian variety to \(A\) is a
  homomorphism.
\end{theorem}

\begin{proof}
  Extend scalars to an algebraic closure and choose an affine neighbourhood of
  the common value on \(\{x_0\}\times Y\).  Properness makes the locus of
  \(x\) for which the \(Y\)-fibre leaves this
  neighbourhood closed.  On the complement, regular functions pulled back
  from the affine target are constant in the \(Y\)-direction; the value at
  \(x_0\) fixes the constants.
  The equalizer is closed because \(A\) is separated and contains a dense open
  of the reduced product, hence it is the whole product.  Apply this to
  \(f(x+y)-f(x)-f(y)\) for the homomorphism assertion.
\end{proof}

\begin{lemma}[Rational graph closure]
  \label{pa-lem-rational-graph}
  \dcref{3.1}
  \cite{milne-av}
  If \(A\) is proper, the graph closure of a rational map \(X\dashrightarrow A\)
  is proper and birational over \(X\).
\end{lemma}

\begin{proof}
  It is closed in \(X\times A\), so its projection is proper; over the dense
  domain of definition it is the original graph.
\end{proof}

\begin{lemma}[Codimension-one points give DVRs]
  \label{pa-lem-codim-one-dvr}
  \dcref{3.2}
  \cite{milne-av,hartshorne-ag}
  A codimension-one point of a nonsingular variety has a DVR as local ring.
\end{lemma}

\begin{proof}
  Its local ring is a one-dimensional regular local domain, hence a DVR.
\end{proof}

\begin{lemma}[Valuative extension at codimension one]
  \label{pa-lem-valuative-extension}
  \dcref{3.2}
  \uses{pa-lem-rational-graph,pa-lem-codim-one-dvr}
  \cite{milne-av}
  A rational map from a nonsingular variety to a proper variety is defined at
  every codimension-one point.
\end{lemma}

\begin{proof}
  Apply the valuative criterion for properness to the DVR in
  \ref{pa-lem-codim-one-dvr}; uniqueness gives a single point of the graph.
\end{proof}

\begin{definition}[Rational map and domain]
  \label{pa-def-rational-map}
  \dcref{3.1}
  \cite{milne-av}
  A rational map \(X\dashrightarrow Y\) is an equivalence class of morphisms
  \(U\to Y\) with \(U\subset X\) dense open; its maximal such \(U\) is the
  domain of definition.
\end{definition}

\begin{lemma}[Rational maps are determined generically]
  \label{pa-lem-rational-generic}
  \dcref{3.1}
  \uses{pa-def-rational-map}
  \cite{milne-av}
  If \(X\) is integral and \(Y\) separated, two rational maps \(X\dashrightarrow
  Y\) agreeing at the generic point agree on the intersection of their domains.
\end{lemma}

\begin{proof}
  Their equalizer is closed in the intersection because \(Y\) is separated and
  contains the generic point.  The intersection is integral, so the equalizer
  contains a dense open and the maps define the same rational class.
\end{proof}

\begin{lemma}[Empty indeterminacy gives a morphism]
  \label{pa-lem-empty-indeterminacy}
  \dcref{3.2}
  \uses{pa-lem-rational-graph,pa-lem-valuative-extension}
  \cite{milne-av}
  If the graph closure of \(f:X\dashrightarrow Y\) has singleton fibres over
  all points of \(X\), then \(f\) extends uniquely to a morphism.
\end{lemma}

\begin{proof}
  The graph projection is proper and quasi-finite, hence finite.  A finite
  birational morphism with singleton fibres to a normal scheme is an
  isomorphism; its inverse is the required extension.
\end{proof}

\begin{lemma}[The Abel factor is a homomorphism]
  \label{pa-lem-abel-factor-homomorphism}
  \dcref{III.6}
  \uses{pa-thm-albanese,pa-thm-rigidity}
  \cite{milne-av}
  The morphism \(u:\operatorname{Pic}^0_{C/k}\to A\) obtained from the
  symmetric-power construction respects addition.
\end{lemma}

\begin{proof}
  Compare the constructions for degrees \(n\) and \(n+1\), using the divisor
  \(P_0\) to embed \(C^{(n)}\) into \(C^{(n+1)}\).  The resulting equality on
  the surjective Abel maps gives \(u(L\otimes M)=u(L)+u(M)\).
\end{proof}

\begin{lemma}[Symmetric sums]
  \label{pa-lem-symmetric-sum}
  \dcref{III.6}
  \uses{pa-def-abel-jacobi}
  \cite{milne-av}
  For \(f:C\to A\), the sum \(f(Q_1)+\cdots+f(Q_n)\) descends to a morphism
  \(C^{(n)}\to A\).
\end{lemma}

\begin{proof}
  The sum is invariant under \(S_n\) because \(A\) is commutative.  The
  quotient property of \(C^{(n)}\) gives the descended morphism.
\end{proof}

\begin{lemma}[Constancy on complete linear systems]
  \label{pa-lem-linear-system-constant}
  \dcref{I.2}
  \uses{pa-lem-effective-map-fibres,pa-thm-rigidity}
  \cite{milne-av}
  A morphism from a complete linear system to an abelian variety is constant.
\end{lemma}

\begin{proof}
  A complete linear system is a projective space.  Its image is complete and
  connected, and the rigidity lemma forces a map from this projective space to
  an abelian variety to be constant.
\end{proof}

\begin{theorem}[Extension of rational maps]
  \label{pa-thm-rational-extension}
  \dcref{3.1,3.2}
  \uses{pa-thm-rigidity}
  \cite[Thms.~3.1--3.2]{milne-av}
  A rational map from a nonsingular variety to an abelian variety extends
  uniquely to a morphism.
\end{theorem}

\begin{proof}
  Take the closure of the graph in \(X\times A\).  Since \(A\) is proper, the
  projection to \(X\) is proper and birational.  At every codimension-one
  point of the nonsingular \(X\), the local ring is a discrete valuation ring,
  and the valuative criterion gives a unique extension there.  The remaining
  indeterminacy has codimension at least two; the rigidity lemma forces every
  fibre of the graph projection to be a singleton.  The graph projection is
  therefore an isomorphism and supplies the unique morphism extending the
  rational map.
\end{proof}

\begin{theorem}[Albanese universal property]
  \label{pa-thm-albanese}
  \dcref{III.6}
  \uses{pa-def-abel-jacobi,pa-thm-pic0-abelian,pa-thm-rigidity}
  \cite{milne-av}
  For every abelian variety \(A/k\) and every morphism
  \(f:C\to A\) with \(f(P_0)=0\), there is a unique homomorphism
  \(u:\operatorname{Pic}^0_{C/k}\to A\) satisfying
  \[
    f=u\circ\iota_{P_0}.
  \]
\end{theorem}

\begin{proof}
  Choose \(n\ge 2g(C)-1\).  The sum of the values of \(f\) on an ordered
  \(n\)-tuple is symmetric, hence descends to \(f_n:C^{(n)}\to A\).  The
  fibres of \(C^{(n)}\to\operatorname{Pic}^n_{C/k}\) are complete linear
  systems, and the rigidity theorem makes \(f_n\) constant on each fibre.
  It therefore descends to \(\operatorname{Pic}^n_{C/k}\).  Translation by a
  degree-\(n\) line bundle gives a morphism
  \(u:\operatorname{Pic}^0_{C/k}\to A\).  Comparing \(n\) and \(n+1\) shows
  \(u\) respects addition and that \(f=u\circ\iota_{P_0}\).  Surjectivity of
  the symmetric-power map gives uniqueness.
\end{proof}

\label{pa-ch-jacobian}

\begin{definition}[Jacobian functor of points]
  \label{pa-def-jacobian-functor}
  \dcref{5.1}
  \uses{pa-def-jacobian}
  \cite{kleiman-picard}
  For \(T\), the Jacobian functor is the degree-zero subgroup of the etale
  Picard sheaf:
  \[
    \operatorname{Jac}_C(T)=
    \ker\bigl(\deg:\operatorname{Pic}_{(C/k)\et}(T)\to\underline{\mathbb Z}(T)\bigr).
  \]
\end{definition}

\begin{lemma}[The Jacobian functor is a group sheaf]
  \label{pa-lem-jacobian-group-sheaf}
  \dcref{5.1}
  \uses{pa-def-jacobian-functor,pa-lem-etale-sheaf-group}
  \cite{kleiman-picard}
  \(\operatorname{Jac}_C\) is a commutative etale sheaf of groups.
\end{lemma}

\begin{proof}
  Degree is additive under tensor product and locally constant in families, so
  its kernel is a subgroup sheaf of the group sheaf in
  \ref{pa-lem-etale-sheaf-group}.
\end{proof}

\begin{lemma}[Representability identifies the Jacobian scheme]
  \label{pa-lem-jacobian-represented}
  \dcref{4.8}
  \uses{pa-def-jacobian-functor,pa-thm-picard-representability}
  \cite{kleiman-picard}
  The functor \(\operatorname{Jac}_C\) is represented by the open-and-closed
  identity component \(\operatorname{Pic}^0_{C/k}\).
\end{lemma}

\begin{proof}
  By representability, the etale Picard sheaf is represented by
  \(\operatorname{Pic}_{C/k}\).  The degree-zero kernel is open and closed,
  and its component containing the identity is exactly
  \(\operatorname{Pic}^0_{C/k}\).
\end{proof}

\begin{lemma}[Changing the base point translates Abel--Jacobi]
  \label{pa-lem-basepoint-translation}
  \dcref{III.6}
  \uses{pa-def-abel-jacobi,pa-def-jacobian}
  \cite{milne-av}
  For \(P_0,P_1\in C(k)\),
  \[
    \iota_{P_1}(Q)=\iota_{P_0}(Q)-\iota_{P_0}(P_1).
  \]
\end{lemma}

\begin{proof}
  Tensor the defining bundles:
  \(\mathcal O_C(Q-P_1)\cong
    \mathcal O_C(Q-P_0)\otimes\mathcal O_C(P_0-P_1)\).
  The second factor is independent of \(Q\), hence is a translation.
\end{proof}

\begin{proposition}[Jacobian base change]
  \label{pa-prop-jacobian-base-change}
  \dcref{III.6}
  \uses{pa-lem-jacobian-represented,pa-lem-flat-cohomology}
  \cite{kleiman-picard}
  For every field extension \(k\subset k'\),
  \[
    \operatorname{Jac}(C)_{k'}\cong\operatorname{Jac}(C_{k'}).
  \]
\end{proposition}

\begin{proof}
  Picard representability and flat cohomology base change identify the degree
  components after extending scalars.  The identity section and tensor law are
  preserved, so the degree-zero identity components identify canonically.
\end{proof}

\begin{lemma}[The universal morphism determines the Jacobian map]
  \label{pa-lem-universal-map-unique}
  \dcref{III.6}
  \uses{pa-thm-albanese,pa-lem-symmetric-sum}
  \cite{milne-av}
  If two homomorphisms \(u,v:\operatorname{Jac}(C)\to A\) agree after
  composition with \(\iota_{P_0}\), then \(u=v\).
\end{lemma}

\begin{proof}
  For \(n\ge2g(C)-1\), the Abel map \(C^{(n)}\to\operatorname{Pic}^n\) is
  surjective.  Agreement on \(\iota_{P_0}\) implies agreement on the sum map
  from \(C^{(n)}\), hence on \(\operatorname{Pic}^n\), and translation
  identifies this with \(\operatorname{Jac}(C)\).
\end{proof}

\begin{definition}[Jacobian]
  \label{pa-def-jacobian}
  \dcref{III.6}
  \uses{pa-def-pic0}
  \cite{milne-av,kleiman-picard}
  \[
    \operatorname{Jac}(C):=\operatorname{Pic}^0_{C/k}.
  \]
\end{definition}

This definition uses the etale Picard scheme; the preceding representability
and identity-component results show that it is independent of the chosen
presentation of the Picard functor.

\begin{theorem}[Jacobian theorem]
  \label{pa-thm-jacobian}
  \dcref{III.6,5.13,5.14,custom}
  \uses{pa-def-jacobian,pa-thm-pic0-abelian,pa-thm-albanese}
  \cite{milne-av,kleiman-picard}
  By \ref{pa-thm-pic0-abelian}, the Jacobian is an abelian variety of dimension
  \(g(C)\), and by \ref{pa-thm-albanese}, \(\iota_{P_0}\) is universal among
  pointed maps from \(C\) to abelian varieties.  Changing \(P_0\) changes
  \(\iota_{P_0}\) by a translation.
\end{theorem}

\begin{proof}
  The Picard-variety theorem makes \(\operatorname{Pic}^0_{C/k}\) an abelian
  variety and computes its dimension from \(H^1(C,\mathcal O_C)\).  The
  Albanese universal property gives the factorisation through
  \(\iota_{P_0}\), and its uniqueness follows from the surjectivity of the
  symmetric-power Abel map.  Replacing \(P_0\) by \(P_1\) tensors the
  corresponding line bundles by \(\mathcal O_C(P_1-P_0)\), which is a
  translation on the Jacobian.
\end{proof}

\begin{theorem}[Base change]
  \label{pa-thm-jacobian-base-change}
  \dcref{III.6,custom}
  \uses{pa-def-jacobian,pa-thm-picard-representability}
  \cite{kleiman-picard}
  For every field extension \(k\subset k'\), there is a canonical isomorphism
  \[
    \operatorname{Jac}(C)\times_k k'\cong
    \operatorname{Jac}(C\times_k k'),
  \]
  compatible with towers and with the Abel--Jacobi maps.
\end{theorem}

\begin{proof}
  The cohomology-and-base-change theorem identifies the degree components of
  the Picard scheme after extending \(k\) to \(k'\).  The identity section and
  tensor product are preserved, so the identity components identify
  canonically.  The diagonal construction of the Abel--Jacobi map is itself
  compatible with base change, giving the final compatibility statement.
\end{proof}


